<?php
$o=$db->one('SELECT o.*,c.name owner_name,c.address owner_address,u.name preparer FROM customer_order o JOIN owner c ON c.id=o.owner_id LEFT JOIN user_account u ON u.id=o.preparer_id WHERE o.id=?',[(int)($_GET['id']??0)]);
$kind=(string)($_GET['kind']??'pick');if(!in_array($kind,['pick','delivery','waybill'],true))throw new DomainException('Document inconnu.');
if($kind!=='pick'&&$o['status']!=='shipped')throw new DomainException('Les documents de livraison sont disponibles après expédition.');
$s=$kind!=='pick'?$db->one('SELECT s.*,v.reference visit_reference,ve.plate,t.plate trailer_plate,c.name carrier_name,c.address carrier_address,d.name driver_name FROM shipment s JOIN truck_visit v ON v.id=s.visit_id JOIN vehicle ve ON ve.id=v.vehicle_id LEFT JOIN vehicle t ON t.id=v.trailer_id JOIN carrier c ON c.id=ve.carrier_id JOIN driver d ON d.id=v.driver_id WHERE s.order_id=?',[$o['id']]):null;
?>
<article class="panel transport-document"><div class="section-heading"><div><p>Transit · Entrepôt de démonstration</p><h1><?= ['pick'=>'Liste de prélèvement FEFO','delivery'=>'Bon de livraison','waybill'=>'Lettre de voiture'][$kind] ?></h1></div><strong><?= h($o['reference']) ?></strong></div><p>Propriétaire : <?= h($o['owner_name']) ?><br>Livraison : <?= h($o['destination']) ?><br>Préparateur : <?= h($o['preparer']??'Non affecté') ?><br>État : <?= h(Catalog::VALUES[$o['status']]) ?></p>
<?php if($s): ?><p>Expédition : <?= h($s['reference']) ?> · <?= h($s['shipped_at']) ?><br>Transporteur : <?= h($s['carrier_name'].' / '.$s['carrier_address']) ?><br>Chauffeur : <?= h($s['driver_name']) ?><br>Véhicule : <?= h($s['plate']) ?><?= $s['trailer_plate']?' / Remorque : '.h($s['trailer_plate']):'' ?><br>Passage : <?= h($s['visit_reference']) ?></p><?php endif; ?>
<?php dataTable($db->all("SELECT a.sku article,a.name designation,l.code lot,l.expires_on dlc,i.pallet_code palette_origine,e.code emplacement,p.qty quantite,p.status etat,c.code colis,c.type conditionnement FROM order_line ol JOIN article a ON a.id=ol.article_id JOIN pick p ON p.order_line_id=ol.id JOIN receipt_item i ON i.id=p.receipt_item_id JOIN lot l ON l.id=i.lot_id JOIN location e ON e.id=p.location_id LEFT JOIN package_pick cp ON cp.pick_id=p.id LEFT JOIN package c ON c.id=cp.package_id WHERE ol.order_id=? ORDER BY a.sku,l.expires_on,p.id",[$o['id']])); ?>
<?php if($kind==='waybill'): ?><div class="signature-grid"><div>Signature expéditeur<br><br><br>________________________</div><div>Signature transporteur<br><br><br>________________________</div><div>Réserves destinataire<br><br><br>________________________</div></div><?php endif; ?><p class="muted">Document pédagogique · Coordonnées et opérations fictives.</p></article><button type="button" class="no-print" data-print>Imprimer ce document</button>
